		const nonce = `${generation}:${Date.now()}:${++heartbeatSequence}`;
		pendingPong = nonce;
		try {
			socket.send(JSON.stringify({ type: "ping", nonce, time: Date.now() }));
		} catch {
			socket.close();
			connect();
			return;
